import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    if n == 0:
        print("")
        return

    goals = list(map(int, data[1:n+1]))

    result = []
    for i in range(n):
        if i < 3:
            sum_last_3 = sum(goals[i:])
        else:
            sum_last_3 = sum(goals[i-2:i+1])
        net_goal = goals[i] - sum_last_3
        result.append(str(net_goal))

    print(" ".join(result))

if __name__ == "__main__":
    main()
